CREATE TABLE game_edition (id BIGINT NOT NULL AUTO_INCREMENT,game_id BIGINT NOT NULL,code VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,name VARCHAR(160) NOT NULL,description MEDIUMTEXT NOT NULL DEFAULT (''),status VARCHAR(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'active',created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),PRIMARY KEY(id),CONSTRAINT uk_game_edition_code UNIQUE(game_id,code),CONSTRAINT ck_game_edition_code CHECK(REGEXP_LIKE(code,'^[a-z0-9-]{2,64}$','c')),CONSTRAINT ck_game_edition_name CHECK(CHAR_LENGTH(TRIM(name)) BETWEEN 1 AND 160),CONSTRAINT ck_game_edition_status CHECK(status IN ('active','inactive')),CONSTRAINT fk_game_edition_game FOREIGN KEY(game_id) REFERENCES game(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
